cd /tmp; E=/Users/dct/.factory/missions/e194b9e3-6a67-42b9-bfc9-dd4e1ac23b0c/evidence/m5/r2/b-panel
S="agent-browser --session ut5r2-panel"
$S get url
cat <<'EOF' | $S eval --stdin > $E/panel-rows.json
(() => { const p=document.querySelector('[aria-label=panel]'); if(!p) return {err:'no panel'};
const q=(sel)=>[...p.querySelectorAll(sel)];
const cells=(tr)=>[...tr.querySelectorAll('th,td')].map(c=>c.innerText.trim());
const pref=(pre)=>q('[aria-label^="'+pre+'"]').map(e=>({label:e.getAttribute('aria-label'),tag:e.tagName,text:e.innerText.trim().replace(/\s+/g,' '),cells:e.tagName=='TR'?cells(e):null}));
const out={};
for (const k of ['usage-role-','usage-lane-','usage-milestone-','usage-waste-','usage-comparison-','waste-group','waste-legend','waste-bar','panel-timeline-row','timeline-legend','sparkline','usage-budget','usage-price-table','throttled','panel-throttled','usage-throttled'])
  out[k]=pref(k);
out.svgAttrs=q('svg').map(s=>({label:s.getAttribute('aria-label'),title:(s.querySelector('title')||{}).textContent,attrs:[...s.attributes].map(a=>a.name+'='+a.value.slice(0,80))}));
out.wasteRects=q('[aria-label=panel-chart-waste] rect').map(r=>[...r.attributes].map(a=>a.name+'='+a.value).join(' '));
out.timelineRowEx=q('[aria-label=panel-timeline-row]').slice(0,2).map(r=>r.outerHTML.slice(0,400));
return out})()
EOF
python3 - <<EOF
import json
d=json.load(open('$E/panel-rows.json'));d=json.loads(d) if isinstance(d,str) else d
for k,v in d.items():
    print('==',k)
    for x in (v if isinstance(v,list) else [v]): print('  ',x)
